import React from 'react';
import { useQuiz } from '../context/QuizContext';
import { generateQuizQuestionsWithAI } from '../services/openaiService';
import { generateIntelligentQuestions } from '../services/intelligentChatbot';

const LoadingScreen = () => {
  const { state, actions } = useQuiz();

  React.useEffect(() => {
    const loadQuestions = async () => {
      try {
        actions.setLoading(true);
        
        // Try intelligent questions first (faster, more accurate)
        let result = await generateIntelligentQuestions(state.selectedTopic);
        
        // If no intelligent questions available, fall back to AI
        if (!result || !result.success) {
          result = await generateQuizQuestionsWithAI(state.selectedTopic);
        }
        
        if (result && result.success) {
          actions.setQuestions(result.questions);
        } else {
          actions.setError('Failed to generate quiz questions');
        }
      } catch (error) {
        actions.setError(error.message);
      }
    };

    loadQuestions();
  }, [state.selectedTopic, actions]);

  return (
    <div className="card">
      <div className="loader">
        <div className="spinner"></div>
        <div className="loading-text">
          AI is generating your {state.selectedTopic} quiz questions...
        </div>
        <div style={{ fontSize: '0.9rem', color: '#a0aec0', marginTop: '10px' }}>
          This may take a few seconds
        </div>
      </div>
    </div>
  );
};

export default LoadingScreen;
